// New TypeScript 5 feature: Type-Only Equality Operators
// type hierarchy in typescript is based on structural typing, which means that two types are considered equal if they have the same structure, regardless of their names.

// any type is a top type in TypeScript, which means that it can be assigned to any other type without causing a type error.

let name1: any = "John Doe"; // noImpleicitly typed as any as true in tsconfig.json

name1 = 12345; // no error because name is of type any
name1 = [1234];
name1 = { name: "John Doe" };
name1 = true;

// check if name1 is equal to string type using type-only equality operator
console.log(`Is name1 equal to string type? ${typeof name1 == "string"}`); // false
console.log(
  `Is name1 strictly equal to string type? ${typeof name1 === "string"}`,
); // false

let name2: string = "Jane Doe";

// check if name2 is equal to string type using type-only equality operator
console.log(`Is name2 equal to string type? ${typeof name2 == "string"}`); // true
console.log(
  `Is name2 strictly equal to string type? ${typeof name2 === "string"}`,
); // true

// unkown type is a top type in TypeScript, which means that it can be assigned to any other type without causing a type error, but it cannot be assigned to any other type without a type assertion or a type guard.
let value: unknown = "Hello, World!"; // value is of type unknown
// check if value is equal to string type using type-only equality operator
console.log(`Is value equal to string type? ${typeof value == "string"}`); // true
console.log(
  `Is value strictly equal to string type? ${typeof value === "string"}`,
); // true

// is Elgible to vote function using type-only equality operator to check if age is number type
function isEligibleToVote(age: unknown): boolean {
  if (typeof age == "number") {
    return age >= 18;
  } else {
    console.log("Age must be a number");
    return false;
  }
}

console.log(`Is 20 eligible to vote? ${isEligibleToVote(20)}`); // true
console.log(`Is "20" eligible to vote? ${isEligibleToVote("20")}`); // Age must be a number, false

