let value3: NumberOrUndefined = 100;
console.log(`Value 3: ${value3}`); // Value 3: 100

let value4: StrinOrNumberOrUndefined = "Hello, TypeScript!";
console.log(`Value 4: ${value4}`); // Value 4: Hello, TypeScript!

function printValue(input: unknown) {
  if (typeof input === "string") {
    console.log(`Input is a string: ${input}`);
  } else if (typeof input === "number") {
    console.log(`Input is a number: ${input}`);
  } else {
    console.log("Input is of unknown type");
  }
}

printValue("Hello, TypeScript!");
printValue(42);
printValue(true);

